import numpy as np
def read(p):
    L=open(p).read().split('\n'); n=int(L[0]); els=[]; P=[]
    for line in L[2:2+n]:
        t=line.split(); els.append(t[0]); P.append([float(x) for x in t[1:4]])
    return els,np.array(P)
els,P=read('opt1.xyz')
with open('view.xyz','w') as f:
    f.write(f"{len(els)}\nview\n")
    for e,p in zip(els,P): f.write(f"{e} {p[0]:.6f} {p[1]:.6f} {p[2]:.6f}\n")
print(len(els))
